local function createHerbToggleButtons()
	herbsContainer:ClearAllChildren();
	herbButtons = {};
	local yOffset = 0;
	local buttonHeight = 30;
	for herbName, isEnabled in pairs(herbs) do
		local buttonFrame = Instance.new("Frame");
		buttonFrame.Name = herbName .. "_Frame";
		buttonFrame.Size = UDim2.new(1, 0, 0, buttonHeight);
		buttonFrame.Position = UDim2.new(0, 0, 0, yOffset);
		buttonFrame.BackgroundColor3 = Color3.fromRGB(35, 35, 35);
		buttonFrame.BorderSizePixel = 0;
		local herbLabel = Instance.new("TextLabel");
		herbLabel.Name = herbName .. "_Label";
		herbLabel.Size = UDim2.new(0.7, 0, 1, 0);
		herbLabel.Position = UDim2.new(0, 0, 0, 0);
		herbLabel.BackgroundTransparency = 1;
		herbLabel.Text = herbName;
		herbLabel.TextColor3 = Color3.fromRGB(255, 255, 255);
		herbLabel.Font = Enum.Font.Gotham;
		herbLabel.TextSize = 12;
		herbLabel.TextXAlignment = Enum.TextXAlignment.Left;
		herbLabel.Parent = buttonFrame;
		local toggleButton = Instance.new("TextButton");
		toggleButton.Name = herbName .. "_Toggle";
		toggleButton.Size = UDim2.new(0.25, 0, 0.7, 0);
		toggleButton.Position = UDim2.new(0.73, 0, 0.15, 0);
		toggleButton.BackgroundColor3 = (isEnabled and Color3.fromRGB(50, 200, 50)) or Color3.fromRGB(200, 50, 50);
		toggleButton.Text = (isEnabled and "ON") or "OFF";
		toggleButton.TextColor3 = Color3.fromRGB(255, 255, 255);
		toggleButton.Font = Enum.Font.GothamBold;
		toggleButton.TextSize = 12;
		toggleButton.Parent = buttonFrame;
		herbButtons[herbName] = {Frame=buttonFrame,Button=toggleButton,Enabled=isEnabled};
		toggleButton.MouseButton1Click:Connect(function()
			herbs[herbName] = not herbs[herbName];
			herbButtons[herbName].Enabled = herbs[herbName];
			herbButtons[herbName].Button.BackgroundColor3 = (herbs[herbName] and Color3.fromRGB(50, 200, 50)) or Color3.fromRGB(200, 50, 50);
			herbButtons[herbName].Button.Text = (herbs[herbName] and "ON") or "OFF";
			for object, data in pairs(herbEspLabels) do
				if (data.Name == herbName) then
					data.Label.Visible = herbs[herbName];
				end
			end
			print("[Herbs ESP] " .. herbName .. " " .. ((herbs[herbName] and "ENABLED") or "DISABLED"));
		end);
		buttonFrame.Parent = herbsContainer;
		yOffset = yOffset + buttonHeight + 2;
	end
	herbsContainer.CanvasSize = UDim2.new(0, 0, 0, yOffset);
end
local function createHerbLabel(herbName, distance)
	local label = Instance.new("TextLabel");
	label.Name = "HERB_" .. herbName;
	label.BackgroundTransparency = 0.8;
	label.BackgroundColor3 = Color3.fromRGB(0, 0, 0);
	label.TextColor3 = Color3.fromRGB(255, 0, 0);
	label.TextStrokeTransparency = 0.3;
	label.TextStrokeColor3 = Color3.new(0, 0, 0);
	label.Font = Enum.Font.GothamBold;
	label.TextSize = 14;
	label.Text = herbName .. " (" .. tostring(math.floor(distance)) .. ")";
	label.Visible = herbs[herbName];
	label.ZIndex = 10;
	label.Size = UDim2.new(0, 180, 0, 30);
	label.Parent = herbsScreenGui;
	return label;
end
local function findHerbInDescendants(object)
	if not object then
		return nil;
	end
	for herbName, _ in pairs(herbs) do
		if object.Name:lower():find(herbName:lower(), 1, true) then
			return herbName;
		end
	end
	if object:IsA("Model") then
		for _, child in ipairs(object:GetChildren()) do
			for herbName, _ in pairs(herbs) do
				if child.Name:lower():find(herbName:lower(), 1, true) then
					return herbName;
				end
			end
		end
	end
	return nil;
end
local function getHerbWorldPosition(object)
	if object:IsA("BasePart") then
		return object.Position;
	elseif object:IsA("Model") then
		local primary = object.PrimaryPart or object:FindFirstChildWhichIsA("BasePart");
		if primary then
			return primary.Position;
		end
		return object:GetPivot().Position;
	end
	return Vector3.new(0, 0, 0);
end
local function updateHerbsESP()
	for object, data in pairs(herbEspLabels) do
		if data.Label then
			data.Label:Destroy();
		end
	end
	herbEspLabels = {};
	local foundCount = 0;
	local function scanFolder(folder)
		for _, item in ipairs(folder:GetDescendants()) do
			if (item:IsA("Model") or item:IsA("BasePart")) then
				local herbName = findHerbInDescendants(item);
				if (herbName and herbs[herbName] and not herbEspLabels[item]) then
					local worldPos = getHerbWorldPosition(item);
					local distance = (camera.CFrame.Position - worldPos).Magnitude;
					local label = createHerbLabel(herbName, distance);
					herbEspLabels[item] = {Label=label,Name=herbName,Object=item,WorldPos=worldPos};
					foundCount = foundCount + 1;
				end
			end
		end
	end
	scanFolder(Workspace);
	herbsStatusText.Text = "Found: " .. foundCount .. "/5 herbs";
	print("[Herbs ESP] Found " .. foundCount .. "/5 herbs");
end
local function createManualsToggleButtons()
	manualsContainer:ClearAllChildren();
	manualsButtons = {};
	local yOffset = 0;
	local buttonHeight = 30;
	for itemName, _ in pairs(exactItemNames) do
		local isEnabled = true;
		local buttonFrame = Instance.new("Frame");
		buttonFrame.Name = itemName .. "_Frame";
		buttonFrame.Size = UDim2.new(1, 0, 0, buttonHeight);
		buttonFrame.Position = UDim2.new(0, 0, 0, yOffset);
		buttonFrame.BackgroundColor3 = Color3.fromRGB(35, 35, 35);
		buttonFrame.BorderSizePixel = 0;
		local itemLabel = Instance.new("TextLabel");
		itemLabel.Name = itemName .. "_Label";
		itemLabel.Size = UDim2.new(0.7, 0, 1, 0);
		itemLabel.Position = UDim2.new(0, 0, 0, 0);
		itemLabel.BackgroundTransparency = 1;
		itemLabel.Text = itemName;
		itemLabel.TextColor3 = Color3.fromRGB(255, 255, 255);
		itemLabel.Font = Enum.Font.Gotham;
		itemLabel.TextSize = 12;
		itemLabel.TextXAlignment = Enum.TextXAlignment.Left;
		itemLabel.Parent = buttonFrame;
		local toggleButton = Instance.new("TextButton");
		toggleButton.Name = itemName .. "_Toggle";
		toggleButton.Size = UDim2.new(0.25, 0, 0.7, 0);
		toggleButton.Position = UDim2.new(0.73, 0, 0.15, 0);
		toggleButton.BackgroundColor3 = Color3.fromRGB(50, 200, 50);
		toggleButton.Text = "ON";
		toggleButton.TextColor3 = Color3.fromRGB(255, 255, 255);
		toggleButton.Font = Enum.Font.GothamBold;
		toggleButton.TextSize = 12;
		toggleButton.Parent = buttonFrame;
		manualsButtons[itemName] = {Frame=buttonFrame,Button=toggleButton,Enabled=true};
		toggleButton.MouseButton1Click:Connect(function()
			manualsButtons[itemName].Enabled = not manualsButtons[itemName].Enabled;
			toggleButton.BackgroundColor3 = (manualsButtons[itemName].Enabled and Color3.fromRGB(50, 200, 50)) or Color3.fromRGB(200, 50, 50);
			toggleButton.Text = (manualsButtons[itemName].Enabled and "ON") or "OFF";
			for object, data in pairs(manualsEspLabels) do
				if (data.Name == itemName) then
					data.Label.Visible = manualsButtons[itemName].Enabled;
				end
			end
			print("[Manuals ESP] " .. itemName .. " " .. ((manualsButtons[itemName].Enabled and "ENABLED") or "DISABLED"));
		end);
		buttonFrame.Parent = manualsContainer;
		yOffset = yOffset + buttonHeight + 2;
	end
	manualsContainer.CanvasSize = UDim2.new(0, 0, 0, yOffset);
end
local function createManualESPLabel(itemName, customColor)
	local label = Instance.new("TextLabel");
	label.Name = "ESP_" .. itemName;
	label.BackgroundTransparency = 1;
	label.TextColor3 = customColor or itemColors[itemName] or Color3.new(1, 1, 1);
	label.TextStrokeTransparency = 0.2;
	label.TextStrokeColor3 = Color3.new(0, 0, 0);
	label.TextTransparency = 0;
	label.Font = Enum.Font.GothamBold;
	label.TextSize = 18;
	label.Text = itemName;
	label.Visible = true;
	label.ZIndex = 10;
	label.Size = UDim2.new(0, 200, 0, 40);
	label.TextScaled = false;
	label.Parent = manualsScreenGui;
	return label;
end
local function isNPC(object)
	local name = object.Name:lower();
	local avoidNames = {bearst=true,clan=true,npc=true,player=true,character=true,marvel=true};
	for avoidName, _ in pairs(avoidNames) do
		if name:find(avoidName) then
			return true;
		end
	end
	if (object:IsA("Model") and object:FindFirstChildOfClass("Humanoid")) then
		return true;
	end
	return false;
end
local function isTargetItem(object)
	local objectName = object.Name;
	if isNPC(object) then
		return nil;
	end
	local lowerObjectName = objectName:lower();
	for itemName, _ in pairs(exactItemNames) do
		if lowerObjectName:find(itemName:lower()) then
			return itemName, itemColors[itemName];
		end
	end
	return nil;
end
local function getManualWorldPosition(object)
	if object:IsA("BasePart") then
		return object.Position;
	elseif object:IsA("Model") then
		return object:GetPivot().Position;
	elseif object:IsA("Attachment") then
		return object.WorldPosition;
	elseif object:IsA("Folder") then
		for _, child in pairs(object:GetChildren()) do
			if child:IsA("BasePart") then
				return child.Position;
			end
		end
	end
	return Vector3.new(0, 0, 0);
end
local function updateManualsESP()
	for object, label in pairs(manualsEspLabels) do
		if label then
			label:Destroy();
		end
	end
	manualsEspLabels = {};
	local foundCount = 0;
	for _, descendant in pairs(Workspace:GetDescendants()) do
		local itemName, itemColor = isTargetItem(descendant);
		if (itemName and not manualsEspLabels[descendant]) then
			local label = createManualESPLabel(itemName, itemColor);
			manualsEspLabels[descendant] = {Label=label,Name=itemName,Object=descendant};
			foundCount = foundCount + 1;
		end
	end
	manualsStatusText.Text = "Found: " .. foundCount .. "/17 manuals";
	print("[Manuals ESP] Found " .. foundCount .. "/17 items");
end
RunService.RenderStepped:Connect(function()
	for object, data in pairs(herbEspLabels) do
		local label = data.Label;
		if (object and object.Parent) then
			local worldPos = data.WorldPos or getHerbWorldPosition(object);
			local screenPos, onScreen = camera:WorldToScreenPoint(worldPos);
			if (onScreen and herbs[data.Name]) then
				local distance = (camera.CFrame.Position - worldPos).Magnitude;
				label.Text = data.Name .. " (" .. tostring(math.floor(distance)) .. ")";
				label.Visible = true;
				label.Position = UDim2.new(0, screenPos.X - (label.AbsoluteSize.X / 2), 0, screenPos.Y - 15);
			else
				label.Visible = false;
			end
		else
			label.Visible = false;
			label:Destroy();
			herbEspLabels[object] = nil;
		end
	end
end);
RunService.RenderStepped:Connect(function()
	for object, data in pairs(manualsEspLabels) do
		local label = data.Label;
		if (object and object:IsDescendantOf(Workspace)) then
			local worldPosition = getManualWorldPosition(object);
			local screenPosition, onScreen = camera:WorldToScreenPoint(worldPosition);
			if (onScreen and manualsButtons[data.Name] and manualsButtons[data.Name].Enabled) then
				label.Visible = true;
				label.Position = UDim2.new(0, screenPosition.X - (label.AbsoluteSize.X / 2), 0, screenPosition.Y - 20);
				local distance = (camera.CFrame.Position - worldPosition).Magnitude;
				label.Text = string.format("%s\n%d studs", data.Name, math.floor(distance));
			else
				label.Visible = false;
			end
		else
			label.Visible = false;
			if (not object or not object:IsDescendantOf(Workspace)) then
				label:Destroy();
				manualsEspLabels[object] = nil;
			end
		end
	end
end);
createHerbToggleButtons();
createManualsToggleButtons();
wait(2);
updateHerbsESP();
updateManualsESP();
